"""Migrated Meridian CRM 4.2 order_fulfilment workflow."""

from typing import Any


def _numeric(value: Any) -> float:
    """Apply legacy empty-string numeric coercion."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError):
        return 0.0


def _lookup_credit_hold(record: dict, tables: dict) -> str:
    """Perform the legacy LOOKUP, excluding soft-deleted account rows."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire one order_fulfilment workflow event using legacy transition semantics."""
    new_record = dict(record)

    # Transitions are evaluated in legacy XML document order.
    if state == "E" and event == "approve":
        if _numeric(record.get("TOT_AMT", "")) > 0:
            return {
                "state": "A",
                "record": new_record,
                "audits": ["ORD_APPR"],
                "notifies": [],
                "matched": True,
            }

    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": new_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": new_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "cancel":
        if _lookup_credit_hold(record, tables) != "Y":
            return {
                "state": "X",
                "record": new_record,
                "audits": ["ORD_CANC"],
                "notifies": [],
                "matched": True,
            }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": new_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": new_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
